package space.glidetv.launcher;
import android.content.Context;import android.graphics.*;import android.os.*;import android.view.View;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Continuous native city scene with a constant-scale panoramic camera and live weather. */
final class CityScene extends View {
 private final Paint paint=new Paint(3),skyPaint=new Paint(3);private final RectF dest=new RectF();private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService loader=Executors.newSingleThreadExecutor();
 private final Path terrain=new Path();private final boolean useCity;private String zoneId=TimeZone.getDefault().getID();private Bitmap dayCity,nightCity,cloud;private boolean running,weatherDay=true,hasSolarTimes;private final long epoch=SystemClock.uptimeMillis();private int weatherCode,skyTop=0xff206795,skyBottom=0xff8faebd;private float daylight=1,windFactor=.6f,cloudCover=0,sunriseHour=6.4f,sunsetHour=17.7f;private final float[] mesh=new float[17*13*2];private int timeOffset=TimeZone.getDefault().getOffset(System.currentTimeMillis());private final float[] randoms=new float[192];private ColorFilter cityLight;
 public CityScene(Context c){super(c);android.content.SharedPreferences scenePrefs=c.getSharedPreferences("home",0);String sceneLocation=scenePrefs.getString("scene_location","");String currentLocation=String.format(Locale.US,"%.4f,%.4f",Double.parseDouble(scenePrefs.getString("weather_latitude","0")),Double.parseDouble(scenePrefs.getString("weather_longitude","0")));useCity="city".equals(scenePrefs.getString("scene_kind",""))&&sceneLocation.equals(currentLocation);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);Random random=new Random(71);for(int n=0;n<randoms.length;n++)randoms[n]=random.nextFloat();setConditions(0,true,Calendar.getInstance().get(Calendar.HOUR_OF_DAY));loader.execute(()->{Bitmap day=useCity?load("city",1):null,night=useCity?load("city-night",1):null,cloudImage=load("cloud",4);handler.post(()->{dayCity=day;nightCity=night;cloud=cloudImage;invalidate();});});}
 private Bitmap load(String name,int sample){try(InputStream in=new FileInputStream(new File(getContext().getSharedPreferences("home",0).getString("scene_path",""),name+".png"))){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;options.inPreferredConfig=Bitmap.Config.HARDWARE;return BitmapFactory.decodeStream(in,null,options);}catch(Exception e){return null;}}
 private float clamp(float x){return Math.max(0,Math.min(1,x));}private int mix(int a,int b,float t){t=clamp(t);return Color.rgb((int)(Color.red(a)*(1-t)+Color.red(b)*t),(int)(Color.green(a)*(1-t)+Color.green(b)*t),(int)(Color.blue(a)*(1-t)+Color.blue(b)*t));}
 public void setTimeZone(String id){zoneId=id;timeOffset=TimeZone.getTimeZone(id).getOffset(System.currentTimeMillis());invalidate();}
 private float clockHour(){timeOffset=TimeZone.getTimeZone(zoneId).getOffset(System.currentTimeMillis());return ((System.currentTimeMillis()+timeOffset)%86400000L)/3600000f;}
 public void setConditions(int code,boolean day,int hour){weatherCode=code;weatherDay=day;float time=clockHour();boolean daytime=hasSolarTimes?time>=sunriseHour&&time<sunsetHour:day;daylight=!hasSolarTimes?(day?1:0):daytime?Math.min(1,Math.min((time-sunriseHour)/.45f+.3f,(sunsetHour-time)/.5f+.3f)):0;daylight=clamp(daylight);float golden=hasSolarTimes&&daytime?Math.max(1-(time-sunriseHour)/.6f,1-(sunsetHour-time)/.65f):0;golden=clamp(golden);
  skyTop=mix(0xff080e27,0xff64b2e9,daylight);skyBottom=mix(0xff24334d,0xffd5ebf5,daylight);skyBottom=mix(skyBottom,0xffebb17c,golden*.6f);if(code>=45){skyTop=mix(skyTop,0xff536a7a,.7f);skyBottom=mix(skyBottom,0xffa7b4bb,.65f);}else if(code==3){skyTop=mix(skyTop,0xff839eaf,.6f);skyBottom=mix(skyBottom,0xffc5d1d6,.5f);}
  skyPaint.setShader(new LinearGradient(0,0,0,Math.max(1,getHeight()),skyTop,skyBottom,Shader.TileMode.CLAMP));float overcast=code==3?.5f:(code>=45?.58f:Math.max(0,(cloudCover-55f)/100f*.28f));if(code>=51)overcast=Math.max(overcast,.38f);int gray=(int)(255-70*overcast);cityLight=overcast>0?new LightingColorFilter(Color.rgb(gray,gray,gray),Color.rgb(0,0,0)):null;invalidate();
 }
 public boolean isDaytime(){float time=clockHour();return hasSolarTimes?time>=sunriseHour&&time<sunsetHour:weatherDay;}
 private float parseHour(String value,float fallback){try{String clock=value.substring(11,16);return Integer.parseInt(clock.substring(0,2))+Integer.parseInt(clock.substring(3,5))/60f;}catch(Exception e){return fallback;}}
 public void setEnvironment(double wind,double cover,String sunrise,String sunset){hasSolarTimes=sunrise.length()>=16&&sunset.length()>=16;if(!Double.isNaN(wind))windFactor=Math.max(.35f,Math.min(2,(float)wind/15));cloudCover=Double.isNaN(cover)?0:(float)cover;sunriseHour=parseHour(sunrise,sunriseHour);sunsetHour=parseHour(sunset,sunsetHour);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){skyPaint.setShader(new LinearGradient(0,0,0,h,skyTop,skyBottom,Shader.TileMode.CLAMP));}
 private final Runnable tick=new Runnable(){public void run(){if(!running)return;invalidate();handler.postDelayed(this,33);}};
 public void setRunning(boolean value){running=value;handler.removeCallbacks(tick);if(value)tick.run();}
 // Kept for HomeActivity compatibility. Motion continues while D-pad focus moves.
 public void pauseMotionFor(long ms){}public void dispose(){setRunning(false);loader.shutdownNow();handler.removeCallbacksAndMessages(null);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);setRunning(focus&&getWindowVisibility()==View.VISIBLE);}@Override public boolean isOpaque(){return true;}
 private void drawLandscape(Canvas c,float w,float h,float seconds){
  for(int layer=0;layer<4;layer++){terrain.reset();terrain.moveTo(0,h);float drift=seconds*.0015f*(layer+1);for(int x=0;x<=40;x++){float u=x/40f;float y=h*(.68f+layer*.075f-(float)Math.sin(u*5.4f+layer*1.7f+drift)*(.08f-layer*.012f)-(float)Math.sin(u*12f+layer*.6f+drift*.7f)*.028f);terrain.lineTo(u*w,y);}terrain.lineTo(w,h);terrain.close();paint.setColor(mix(0xff101b30+layer*0x010100,0xff657e83-layer*0x0d0e0b,daylight));c.drawPath(terrain,paint);}
 }
 @Override public void onDraw(Canvas c){float w=getWidth(),h=getHeight(),seconds=(SystemClock.uptimeMillis()-epoch)/1000f;c.drawRect(0,0,w,h,skyPaint);paint.setColorFilter(null);paint.setAlpha(255);
  float time=((System.currentTimeMillis()+timeOffset)%86400000L)/3600000f;
  if(dayCity==null)drawLandscape(c,w,h,seconds);
  if(dayCity!=null){Bitmap reference=nightCity!=null?nightCity:dayCity;float cityWidth=Math.max(w,h*reference.getWidth()/(float)reference.getHeight());float route=(float)(.5+.5*Math.sin(seconds*Math.PI*2/144));float cameraLeft=-(cityWidth-w)*route;int index=0;for(int row=0;row<=12;row++)for(int col=0;col<=16;col++){float px=col/16f,py=row/12f,edge=Math.max(clamp((.22f-px)/.22f),clamp((px-.91f)/.09f)),height=clamp((py-.52f)/.12f)*clamp((.98f-py)/.3f);mesh[index++]=px*cityWidth+cameraLeft+(float)Math.sin(seconds*.7f+py*5)*w*.0028f*windFactor*edge*height;mesh[index++]=py*h;}paint.setColorFilter(cityLight);paint.setAlpha((int)(daylight*255));c.drawBitmapMesh(dayCity,16,12,mesh,0,null,0,paint);if(nightCity!=null){paint.setColorFilter(null);paint.setAlpha((int)((1-daylight)*255));c.drawBitmapMesh(nightCity,16,12,mesh,0,null,0,paint);}paint.setAlpha(255);paint.setColorFilter(null);}
  if(daylight<.5f&&weatherCode<=2&&cloudCover<60){for(int n=0;n<42;n++){int a=(int)((1-daylight)*(70+100*(.5f+.5f*(float)Math.sin(seconds*.6+n))));paint.setColor((a<<24)|0x00dceaff);c.drawCircle(randoms[n]*w,randoms[n+48]*h*.58f,n%5==0?1.6f:1,paint);}}
  if(cloud!=null){paint.setColor(Color.WHITE);paint.setColorFilter(null);int count=weatherCode==0?0:weatherCode==1?(cloudCover>=15?1:0):weatherCode==2?Math.max(2,Math.min(4,(int)(cloudCover/20))):weatherCode==3?6:weatherCode==45||weatherCode==48?1:6;for(int n=0;n<count;n++){float width=w*(.36f+randoms[n]*.25f),height=width*cloud.getHeight()/cloud.getWidth(),x=((randoms[n+12]*1.8f+seconds*(.009f+n*.0015f)*windFactor)%1.9f-.6f)*w,y=h*(.05f+randoms[n+24]*.31f);paint.setAlpha((int)((weatherCode>=45?165:weatherCode>=2?115:65)*(daylight*.7f+.3f)));dest.set(x,y,x+width,y+height);c.drawBitmap(cloud,null,dest,paint);}}
  if(daylight<.4f){paint.setStrokeWidth(1.5f);for(int n=0;n<12;n++){paint.setColor(((int)(20*(1-daylight)*(1+Math.sin(seconds*.4+n)))<<24)|0x00ffd39b);float x=(.13f+randoms[n]*.73f)*w,y=(.84f+randoms[n+40]*.1f)*h;c.drawCircle(x,y,1.5f,paint);}}
  if((weatherCode>=51&&weatherCode<=67)||(weatherCode>=80&&weatherCode<=82)||weatherCode>=95){paint.setAlpha(255);paint.setColor(0x55deefff);paint.setStrokeWidth(1.4f);for(int n=0;n<60;n++){float x=(randoms[n]+seconds*.019f)%1,y=(randoms[n+64]+seconds*.29f)%1;c.drawLine(x*w,y*h,x*w-5,y*h+18,paint);}}
  if((weatherCode>=71&&weatherCode<=77)||weatherCode==85||weatherCode==86){paint.setColor(0xaadff4ff);for(int n=0;n<48;n++){float x=(randoms[n]+seconds*.003f*(n%2==0?1:-1)+10)%1,y=(randoms[n+64]+seconds*.025f)%1;c.drawCircle(x*w,y*h,1.5f+n%3,paint);}}
  paint.setAlpha(255);paint.setColorFilter(null);c.drawColor(daylight>.8f&&weatherCode<3?0x10050e19:0x23050e19);
 }
}
